const KEY='exam-dost-v1';const blank=()=>({profile:null,topics:{},saved:[],marked:[],attempts:[],tasks:[],exams:{},settings:{theme:'light',goal:'Complete important topics',availability:[60,90,90,90,90,90,120],slot:'Evening',autoPlan:false}});
let state=blank();let storageOK=true;try{const raw=localStorage.getItem(KEY);if(raw)state={...state,...validateBackup(JSON.parse(raw))};}catch(e){storageOK=false;}
state.settings={...blank().settings,...state.settings};
let unitFilter='all',savedOnly=false,resultFilter='all',planFilter='today',pyqKind='original',pyqYear='all',navigatorOpen=false,installPrompt=null,currentStart=null,toastTimer,openSolutions=new Set();
const scrolls=new Map();const viewStates=new Map();let previousHash=location.hash;const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(KEY,JSON.stringify({app:'exam-dost',version:1,state}));storageOK=true;}catch{storageOK=false;toast('Storage is unavailable or full. Export a backup before leaving.');}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
const icons={home:'<path d="m3 9 9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><polyline points="9 22 9 12 15 12 15 22"/>',book:'<path d="M4 19.5v-15A2.5 2.5 0 0 1 6.5 2H20v20H6.5a2.5 2.5 0 0 1-2.5-2.5Z"/><path d="M6 2v20"/><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/>',document:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/>',trophy:'<path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"/><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0 0 12 0V2z"/>',network:'<circle cx="5" cy="12" r="3"/><circle cx="18" cy="5" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8 11 7-5m-7 7 7 5"/>',chip:'<rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4"/>',nodes:'<circle cx="12" cy="4" r="3"/><circle cx="4" cy="19" r="3"/><circle cx="20" cy="19" r="3"/><path d="m10 7-5 9m9-9 5 9M7 19h10"/>',database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',tree:'<rect x="9" y="2" width="6" height="6" rx="1"/><rect x="1" y="17" width="6" height="6" rx="1"/><rect x="17" y="17" width="6" height="6" rx="1"/><path d="M12 8v5H4v4m8-4h8v4"/>',bell:'<path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.73 21a2 2 0 0 1-3.46 0"/>',menu:'<line x1="4" y1="12" x2="20" y2="12"/><line x1="4" y1="6" x2="20" y2="6"/><line x1="4" y1="18" x2="20" y2="18"/>',check:'<polyline points="20 6 9 17 4 12"/>',arrow:'<line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/>',back:'<line x1="19" y1="12" x2="5" y2="12"/><polyline points="12 19 5 12 12 5"/>',chevron:'<polyline points="9 18 15 12 9 6"/>',calendar:'<rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/>',clock:'<circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/>',user:'<path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/>',save:'<path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"/><polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/>',download:'<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/>',upload:'<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z"/>',shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/>',search:'<circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/>',grid:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/>',close:'<line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>',info:'<circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/>',sun:'<circle cx="12" cy="12" r="5"/><line x1="12" y1="1" x2="12" y2="3"/><line x1="12" y1="21" x2="12" y2="23"/><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/><line x1="1" y1="12" x2="3" y2="12"/><line x1="21" y1="12" x2="23" y2="12"/><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/>',star:'<polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/>',phone:'<rect x="5" y="2" width="14" height="20" rx="2"/><line x1="12" y1="18" x2="12.01" y2="18"/>',sparkles:'<path d="m12 3-1.9 5.8a2 2 0 0 1-1.3 1.3L3 12l5.8 1.9a2 2 0 0 1 1.3 1.3L12 21l1.9-5.8a2 2 0 0 1 1.3-1.3L21 12l-5.8-1.9a2 2 0 0 1-1.3-1.3z"/>'};
function icon(n,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.book}</svg>`;}
function btn(text,action,cls='',extra=''){return `<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;}
function link(text,path,cls=''){return `<a class="${cls}" href="#${path}">${text}</a>`;}
function go(path){location.hash=path;}
const route=()=>location.hash.slice(1).split('/').filter(Boolean);const subject=id=>subjects.find(s=>s.id===id)||subjects[0];
function hero(tag,title,sub,tone='green',art='study'){return `<section class="hero ${tone}"><div><span class="eyebrow">${tag}</span><h1>${title}</h1><p>${sub}</p></div><div class="hero-art">${art==='study'?'<img src="./assets/study.png" alt="Books and study calendar">':`<img src="./assets/${art==='quiz'?'quiz':art==='paper'?'paper':'study'}.png" alt="">`}</div></section>`;}
function profileInitial(){return esc(Array.from(state.profile?.name.trim()||'?')[0].toLocaleUpperCase());}
function profileButton(){return link(`<span aria-hidden="true">${profileInitial()}</span><span class="sr-only">My Profile</span>`,'/profile','round profile-link profile-initial');}
function top(title,sub=''){return `<header class="subheader"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${profileButton()}</header>`;}
function header(){return `<header class="main-header"><a class="wordmark" href="#/home"><img src="./assets/logo-horizontal.png" alt="BEU Exam Dost" class="brand-logo-light"><img src="./assets/logo-horizontal-dark.png" alt="BEU Exam Dost" class="brand-logo-dark"><span class="sr-only">BEU Exam Dost</span></a><div class="header-actions">${btn(icon('bell')+'<span class="notif-pip" aria-hidden="true"></span>','reminders','round notif-btn','aria-label="Study reminders"')}${profileButton()}</div></header>`;}
function nav(active){return `<nav class="bottom-nav" aria-label="Main navigation">${[['home','home','Home'],['subjects','book','Subjects'],['pyqs','document','PYQs'],['quiz','trophy','Quiz']].map(([id,ic,t])=>link(`<img class="nav-icon-3d" src="./assets/nav-${id}.webp" alt="" width="32" height="32"><span>${t}</span>`,'/'+id,active===id?'active':'')).join('')}</nav>`;}
function back(path='/home'){return `<div class="back-dock">${link(icon('back')+' Back',path,'back-pill')}</div>`;}
function page(html,{active=null,parent='/home',main=false}={}){return `<div class="app-shell">${main?header():''}<main id="main">${html}</main>${active?nav(active):back(parent)}</div>`;}
function percent(ts){let done=ts.filter(t=>state.topics[t.id]).length;return {done,total:ts.length,pct:ts.length?Math.round(done/ts.length*100):0};}
function bar(p,color='green'){return `<div class="progress-track ${color}" role="progressbar" aria-valuenow="${p}" aria-valuemin="0" aria-valuemax="100"><span style="width:${p}%"></span></div>`;}
function ring(p){return `<div class="ring" style="--p:${p}"><b>${p}%</b></div>`;}
function subjectCards(target,sub=''){return `<div class="subject-list">${subjects.map(s=>{let p=percent(s.units.flatMap(u=>u.topics));return link(`<span class="subject-icon ${s.color}">${icon(s.icon)}</span><div class="subject-content"><span class="badge ${s.color}">${s.short}</span><h3>${s.name}</h3><p>${sub||`${p.done} of ${p.total} topics completed`}</p>${sub?'':bar(p.pct,s.color)}</div>${icon('chevron')}`,target(s),'subject-card card');}).join('')}</div>`;}
function setup(edit=false){let p=state.profile||{};const legacyBranches={'CSE (Artificial Intelligence & Machine Learning)':branches[4],'CSE (Data Science)':branches[5],'CSE (Cyber Security)':branches[2],'CSE (Internet of Things)':branches[3]};const selectedBranch=legacyBranches[p.branch]||p.branch;const selectedCollege=p.college||'';return `<div class="app-shell setup-shell"><main>${!edit?'<div class="wordmark setup-brand"><img src="./assets/logo-horizontal.png" alt="BEU Exam Dost" class="brand-logo-light"><img src="./assets/logo-horizontal-dark.png" alt="BEU Exam Dost" class="brand-logo-dark"><span class="sr-only">BEU Exam Dost</span></div>':top('Edit profile')}${hero('YOUR STUDY COMPANION',edit?'Make it yours.':'Your exam journey<br>starts here.','Tell us a little about yourself.','blue')}<form id="profile-form" class="card form-card"><h2>${edit?'Your details':'Set up your profile'}</h2><label>Your name<input name="name" required maxlength="100" placeholder="Enter your name" autocomplete="name" value="${esc(p.name||'')}"></label><label>College<select name="college" required id="college-select"><option value="">Select your college</option>${selectedCollege&&!colleges.includes(selectedCollege)?`<option value="${esc(selectedCollege)}" selected>${esc(selectedCollege)}</option>`:''}${colleges.map(c=>`<option value="${esc(c)}" ${selectedCollege===c?'selected':''}>${esc(c)}</option>`).join('')}<option value="Other Engineering College" ${selectedCollege==='Other Engineering College'?'selected':''}>Other Engineering College</option></select></label><label>Branch<select name="branch" required><option value="">Select your branch</option>${selectedBranch&&!branches.includes(selectedBranch)?`<option selected>${esc(selectedBranch)}</option>`:''}${branches.map(b=>`<option ${selectedBranch===b?'selected':''}>${esc(b)}</option>`).join('')}</select></label><p class="muted small">All 58 BEU affiliated colleges available. CSE and supported specialisation branches share the same study content.</p><button class="primary full">${edit?'Save changes':'Get started'} ${icon('arrow')}</button></form><p class="footnote">No account needed. Set up once on this device.</p></main>${edit?back('/profile'):''}</div>`;}
function home(){let p=percent(allTopics),today=dateKey();let tasks=state.tasks.filter(t=>t.date===today).slice(0,3);let upcoming=subjects.filter(s=>examDates[s.id]&&examDates[s.id]>=today).sort((a,b)=>examDates[a.id].localeCompare(examDates[b.id]))[0];let days=upcoming?Math.ceil((new Date(examDates[upcoming.id]+'T00:00:00')-new Date(today+'T00:00:00'))/86400000):0;return page(`${hero('YOUR STUDY COMPANION','A little progress,<br>every day.',`Let’s make today count, ${esc(state.profile.name.split(' ')[0])}.`)}<section class="card next-exam"><div><span class="badge green">Next exam</span><h2>${upcoming?upcoming.name:'Exams complete. Well done.'}</h2><p>${upcoming?`${days===0?'Today':days+' days to go'} · ${formatDate(examDates[upcoming.id])} · ${examSession.label}`:'Your scheduled exams have finished. Keep learning at your own pace.'}</p>${link('View exam schedule '+icon('arrow'),'/planner','text-link')}</div><span class="calendar-art">${upcoming?`<strong>${days}</strong><small>DAYS</small>`:icon('calendar')}</span></section><section class="card summary mint"><div><h2>Your preparation</h2><p>${p.done} of ${p.total} topics completed</p>${bar(p.pct)}</div>${ring(p.pct)}</section><div class="section-heading"><h2>Today’s plan</h2>${link('View all '+icon('arrow'),'/planner','text-link')}</div>${tasks.length?`<section class="card task-list">${tasks.map(taskRow).join('')}</section>`:`<section class="card empty"><span class="subject-icon green">${icon('calendar')}</span><h3>A fresh start awaits.</h3><p>Choose your study time and build today’s plan.</p>${link('Plan my preparation','/planner','button primary')}</section>`}<div class="section-heading"><h2>Keep learning</h2></div><div class="shortcut-grid">${link(icon('document')+'<div><h3>Important PYQs</h3><p>Questions that matter</p></div>','/pyqs','shortcut mint')}${link(icon('trophy')+'<div><h3>Master Quiz</h3><p>Test your concepts</p></div>','/quiz/master','shortcut lavender')}</div><p class="footnote">Your progress stays on this device.</p>`,{active:'home',main:true});}
function subjectsPage(){let p=percent(allTopics);return page(`${hero('YOUR SYLLABUS','My Subjects','One topic at a time. You’ve got this.')}<section class="card summary"><div><p>Overall syllabus progress</p><h2>${p.done} of ${p.total} topics completed</h2><p>6 subjects · Your progress, in one place</p></div>${ring(p.pct)}</section><div class="section-heading"><h2>Your subjects</h2><span>6 subjects</span></div>${subjectCards(s=>'/subjects/'+s.id)}`,{active:'subjects',main:true});}
function subjectPage(id){let s=subject(id),p=percent(s.units.flatMap(u=>u.topics));return page(`${top(s.name,'Subjects / Unit overview')}${hero(s.short+' · SUBJECT OVERVIEW',s.name,'Build concepts. Track every topic.',s.color)}<section class="card summary"><div><p>Your syllabus progress</p><h2>${p.done} of ${p.total} topics completed</h2><span class="badge green">6 units</span> <span class="muted small">${p.total-p.done} topics remaining</span></div>${ring(p.pct)}</section><div class="section-heading"><h2>Your units</h2><span>Tap a unit to explore</span></div><div class="unit-list">${s.units.map(u=>{let x=percent(u.topics);return link(`<span class="unit-no ${u.color}">${String(u.id).padStart(2,'0')}</span><div class="unit-content"><div class="unit-title"><h3>${u.title}</h3>${u.important?'<span class="badge coral">☆ Important unit</span>':''}</div><p>${u.topics.map(t=>t.title).join(' · ')}</p><div class="unit-status"><small>${x.done} of ${x.total} topics</small><span class="badge ${x.pct===100?'green':'neutral'}">${x.pct===100?'✓ Completed':x.done?'In progress':'Not started'}</span></div>${bar(x.pct,u.color)}</div>${icon('chevron')}`,`/subjects/${s.id}/${u.id}`,'card unit-card');}).join('')}</div>`,{parent:'/subjects'});}
function unitPage(id,num){let s=subject(id),u=s.units.find(u=>u.id===+num)||s.units[0],p=percent(u.topics);let list=u.topics.filter(t=>unitFilter==='all'||(unitFilter==='done'?state.topics[t.id]:!state.topics[t.id]));return page(`${top(s.name,`Unit ${String(u.id).padStart(2,'0')} of 06`)}<div class="right-link">${link(icon('grid')+' All units','/subjects/'+s.id,'text-link')}</div>${hero('UNIT '+String(u.id).padStart(2,'0'),u.title,'Your topic checklist',u.color)}<section class="card summary"><div><p>Unit progress</p><h2>${p.done} of ${p.total} topics completed</h2><p>${p.total-p.done} topics left to cover</p></div>${ring(p.pct)}</section><div class="chips">${[['all',`All (${p.total})`],['pending',`Pending (${p.total-p.done})`],['done',`Completed (${p.done})`]].map(([v,t])=>btn(t,'unit-filter','chip '+(unitFilter===v?'selected':''),`data-value="${v}"`)).join('')}</div><div class="section-heading"><h2>Topic checklist</h2></div><p class="muted small">Tick a topic when you finish studying.</p><div class="topics">${list.map(t=>`<label class="card topic"><input type="checkbox" data-topic="${t.id}" ${state.topics[t.id]?'checked':''}><span class="check-ui">${icon('check')}</span><span class="topic-title">${t.title}</span><span class="badge ${state.topics[t.id]?'green':t.important?'coral':'neutral'}">${state.topics[t.id]?'✓ Done':t.important?'High priority':'Study'}</span></label>`).join('')||'<div class="card empty">No topics in this filter.</div>'}</div><div class="unit-travel">${u.id>1?link(icon('back')+`<div>Previous unit<small>${s.units[u.id-2].title}</small></div>`,`/subjects/${s.id}/${u.id-1}`,'button outline'):''}${link(`<div>${u.id<6?'Next unit':'All units'}<small>${u.id<6?s.units[u.id].title:'Back to the overview'}</small></div>`+icon('arrow'),u.id<6?`/subjects/${s.id}/${u.id+1}`:'/subjects/'+s.id,'button primary')}</div>`,{parent:'/subjects/'+s.id});}
function pyqIndex(){return page(`${hero('PREVIOUS YEAR QUESTIONS','Practice with purpose.','Important 7-mark written questions, organised by subject.','orange','paper')}<div class="card notice">${icon('document')}<div><h3>Official 7-Mark Written PYQs</h3><p>Browse by unit and see Bihar Engineering University paper-year trends.</p></div></div><div class="section-heading"><h2>Choose your subject</h2><span>6 subjects</span></div>${subjectCards(s=>'/pyqs/'+s.id,'View important questions')}`,{active:'pyqs',main:true});}
function renderSolution(sol,totalMarks){if(!sol)return"";return`<div class="solution-panel" id="solution-${sol.id||"panel"}"><div class="solution-header"><span class="badge verified-pill">${esc(sol.verified||"BEU Verified Model Answer · 7 Marks")}</span><span class="solution-tagline">Senior PYQ Solver Model Solution</span></div>${sol.intro?`<div class="solution-intro"><p>${sol.intro}</p></div>`:""}${sol.diagrams&&sol.diagrams.length?sol.diagrams.map(diag=>`<div class="solution-diagram-card"><div class="diagram-header"><span class="diagram-tag">PICTORIAL REPRESENTATION</span><span class="diagram-title">${esc(diag.title)}</span></div><div class="ascii-scroll-container"><pre class="solution-ascii">${esc(diag.ascii)}</pre></div></div>`).join(""):""}${sol.table?`<div class="solution-table-card"><h5>${esc(sol.table.title)}</h5><div class="table-scroll"><table class="solution-table"><thead><tr>${sol.table.headers.map(h=>`<th>${esc(h)}</th>`).join("")}</tr></thead><tbody>${sol.table.rows.map(row=>`<tr>${row.map(cell=>`<td>${esc(cell)}</td>`).join("")}</tr>`).join("")}</tbody></table></div></div>`:""}${sol.sections&&sol.sections.length?sol.sections.map(sec=>`<div class="solution-section"><h4>${esc(sec.heading)}</h4><ul class="solution-points">${sec.points.map(pt=>`<li>${pt}</li>`).join("")}</ul></div>`).join(""):""}${sol.conclusion?`<div class="solution-conclusion"><p><b>Conclusion:</b> ${sol.conclusion}</p></div>`:""}${sol.markingScheme&&sol.markingScheme.length?`<div class="marking-scheme-card"><div class="marking-header"><span class="marking-icon">📋</span><h5>BEU Point-wise Marking Scheme</h5></div><div class="table-scroll"><table class="marking-table"><thead><tr><th style="text-align:left;">Evaluation Component</th><th style="width:90px;text-align:right;">Marks</th></tr></thead><tbody>${sol.markingScheme.map(m=>`<tr><td style="text-align:left;">${esc(m.component)}</td><td style="text-align:right;font-weight:700;color:var(--forest);">${esc(m.marks)}</td></tr>`).join("")}</tbody><tfoot><tr><th style="text-align:left;">Total Question Marks</th><th style="text-align:right;color:var(--forest);font-weight:800;">${totalMarks}.0</th></tr></tfoot></table></div></div>`:""}${sol.examTip?`<div class="exam-tip-card"><span class="exam-tip-badge">💡 Senior Solver Exam Tip</span><p>${esc(sol.examTip)}</p></div>`:""}</div>`;}
function pyqSubject(id){let s=subject(id),all=pyqs(s.id);let originalItems=all.filter(q=>q.kind==='original');let effectiveKind=pyqKind||(originalItems.length?'original':'important');let years=[...new Set(originalItems.map(q=>q.source?.year).filter(Boolean))].sort((a,b)=>b-a);if(!years.length)years=[2024,2023,2022];let counts=yearCounts(originalItems,years);let list=filterWrittenQuestions(all,{kind:effectiveKind,unit:unitFilter,year:pyqYear,savedOnly,saved:state.saved});let kindTitle=effectiveKind==='original'?'Original PYQs':'Important 7-Mark Questions';return page(`${top(s.name,kindTitle)}${hero(s.short+' · QUESTION BANK',kindTitle,'Unit-wise questions & verified solutions.','orange','paper')}${renderQuestionFilters({kind:effectiveKind,unit:unitFilter,year:pyqYear,units:s.units,years,savedOnly})}<div class="section-heading"><h2>${effectiveKind==='original'?'Verified Original Exam Questions':'Important 7-Mark Model Questions'}</h2><span>${list.length} questions available</span></div><div class="pyq-list">${list.map(q=>{let isOpen=openSolutions.has(q.id);let uTitle=(s.units[q.unit-1]&&s.units[q.unit-1].title)?s.units[q.unit-1].title:'Core Subject Module';let sourceChip=esc(questionSourceLabel(q));let sourceLink=q.source?.url?` <a class="source-link" href="${esc(q.source.url)}" target="_blank" rel="noopener noreferrer">Official paper</a>`:q.source?.bundled?` <span class="muted small source-meta">Bundled: ${esc(q.source.bundled)}</span>`:'';return `<article class="card pyq-card" id="card-${q.id}"><div class="pyq-title"><span class="badge ${colors[(q.unit-1)%colors.length]}">Unit ${String(q.unit).padStart(2,'0')}</span><h3>${esc(uTitle)}</h3><span class="badge neutral verified-chip">${sourceChip}</span></div><p class="question-text">${esc(q.question)}</p><div class="years"><span class="badge orange">${q.marks||7} marks</span>${q.source?.year?`<span class="muted small">Asked in</span><span class="badge orange">${q.source.year}</span>`:''}${sourceLink}</div><div class="pyq-actions">${btn(icon(state.marked.includes(q.id)?'check':'grid')+(state.marked.includes(q.id)?' Marked':' Mark'),'mark','text-link',`data-id="${q.id}" aria-pressed="${state.marked.includes(q.id)}"`)}${q.solution?btn(icon('document')+(isOpen?' Hide Solution':' View '+(q.marks||7)+'-Mark Solution'),'toggle-solution','button small '+(isOpen?'is-active':'outline-solution'),`data-id="${q.id}" aria-expanded="${isOpen}"`):''}${btn(icon('save')+(state.saved.includes(q.id)?' Saved':' Save'),'save-question','text-link '+(state.saved.includes(q.id)?'amber':''),`data-id="${q.id}" aria-pressed="${state.saved.includes(q.id)}"`)}</div>${isOpen?renderSolution(q.solution,q.marks||7):''}</article>`;}).join('')||`<div class="card empty">${esc(questionEmptyState(effectiveKind,savedOnly))}</div>`}</div>${effectiveKind==='original'?`<section class="card analysis"><h2>Unit-wise year analysis</h2><p class="muted small">Recurrence frequency across recent Bihar Engineering University question papers.</p><div class="table-scroll"><table><thead><tr><th>Unit</th>${years.map(y=>`<th>${y}</th>`).join('')}<th>Total</th></tr></thead><tbody>${counts.map((row,i)=>`<tr><th>${String(i+1).padStart(2,'0')}</th>${row.map(n=>`<td>${n}</td>`).join('')}<td><b>${row.reduce((a,b)=>a+b,0)}</b></td></tr>`).join('')}</tbody><tfoot><tr><th>Total</th>${years.map((_,j)=>`<td>${counts.reduce((a,r)=>a+r[j],0)}</td>`).join('')}<td>${counts.flat().reduce((a,b)=>a+b,0)}</td></tr></tfoot></table></div><p class="small muted">Unit classification follows the official BEU B.Tech CSE syllabus. Topics with higher frequencies represent primary exam targets.</p></section>`:`<section class="card analysis"><h2>Syllabus-Aligned Practice</h2><p class="muted small">Syllabus-aligned practice; not claimed as a previous paper question.</p></section>`}`,{parent:'/pyqs'});}
function quizIndex(){return page(`${hero('QUIZ ZONE','Test yourself.<br>Grow stronger.','Choose your quiz type to get started.','purple','quiz')}<div class="section-heading"><h2>How would you like to practise?</h2></div><p class="muted">Pick a quiz type. Choose your subject next.</p>${[['pyq','FROM EXAM PAPERS','PYQ MCQ Quiz','Attempt original MCQs from previous-year question papers.','orange','paper','Year-wise questions · Answer explanations'],['master','SYLLABUS-BASED PRACTICE','Syllabus Master Quiz','Challenge your concepts with advanced syllabus-based MCQs.','purple','quiz','Unit-wise coverage · Mistake review']].map(([id,tag,title,sub,tone,art,features])=>link(`<span class="eyebrow">${tag}</span><img class="mode-art" src="./assets/${art==='paper'?'paper':'quiz'}.png" alt=""><h2>${title}</h2><p>${sub}</p><span class="mode-features">${features}</span><strong>Choose subject ${icon('arrow')}</strong>`,'/quiz/'+id,'card mode-card '+tone)).join('')}<p class="footnote">Your quiz progress stays on this device.</p>`,{active:'quiz',main:true});}
function quizSubjects(type){let master=type==='master';return page(`${top(master?'Syllabus Master Quiz':'PYQ MCQ Quiz','Quiz / Choose subject')}${hero(master?'SYLLABUS-BASED PRACTICE':'FROM PREVIOUS-YEAR PAPERS',master?'Go beyond memorising.':'Pick a subject.<br>Take the challenge.',master?'Understand. Apply. Master.':'Original exam MCQs, organised by subject.',master?'purple':'orange',master?'quiz':'paper')}<div class="card features"><span>${icon(master?'book':'calendar')}${master?'Unit-wise coverage':'Year-wise MCQs'}</span><span>${icon('info')}Explanations & review</span></div><div class="section-heading"><h2>Choose your subject</h2><span>6 subjects</span></div>${subjectCards(s=>`/quiz/${type}/${s.id}`,master?'Advanced syllabus-based MCQs':'Original previous-year paper MCQs')}<p class="footnote">${master?'Syllabus-aligned master practice questions':'Original previous-year paper MCQs with step-by-step explanations'}</p>`,{parent:'/quiz'});}
function weightageSection(subjectId){let list=unitWeightage[subjectId];if(!list||!list.length)return '';let totalMarks=list.reduce((n,w)=>n+w.marks,0)||70;let segColors=['#10b981','#3b82f6','#8b5cf6','#f97316','#14b8a6','#eab308'];return `<section class="weightage-section"><div class="section-heading"><h2>Exam Weightage & Concept Flow</h2><span>BEU Unit Distribution</span></div><div class="weightage-meter-wrap"><div style="display:flex;justify-content:space-between;align-items:center;"><b>Subject Marks Distribution</b><span class="badge purple">${totalMarks} Marks Evaluated</span></div><div class="weightage-meter" role="progressbar" aria-label="Unit marks weightage" aria-valuenow="100" aria-valuemin="0" aria-valuemax="100">${list.map((w,i)=>`<div class="weightage-segment" style="width:${(w.marks/totalMarks*100).toFixed(1)}%;background:${segColors[i%segColors.length]};" title="Unit ${w.unit}: ${w.marks} marks (${Math.round(w.marks/totalMarks*100)}%)"></div>`).join('')}</div><div class="weightage-legend">${list.map((w,i)=>`<span class="weightage-legend-item"><span class="legend-dot" style="background:${segColors[i%segColors.length]}"></span>Unit ${w.unit} (${w.marks}M · ${Math.round(w.marks/totalMarks*100)}%)</span>`).join('')}</div></div><div class="section-heading"><h2>Unit-Wise Topic Roadmap</h2><span>Chronological Flow</span></div><div style="display:flex;flex-direction:column;gap:0.85rem;">${list.map(w=>`<div class="flow-card"><div class="flow-header"><span class="badge ${colors[(w.unit-1)%colors.length]}">Unit ${w.unit}</span><h4>${esc(w.title)}</h4><span class="badge ${w.priority==='CRITICAL'?'coral':w.priority==='VERY HIGH'?'orange':'green'}">${w.priority}</span><span class="flow-marks">${w.marks} Marks</span></div><div class="flow-path"><span class="flow-label">Question & Concept Flow</span><p class="flow-text">${esc(w.flow)}</p></div><div class="flow-meta"><span>${w.mcqs} High-Yield MCQs · ${w.pyqs} Written Questions (7M)</span>${btn('Practice Unit '+icon('arrow'),'practice-unit','button outline small-btn',`data-subject="${subjectId}" data-unit="${w.unit}"`)}</div></div>`).join('')}</div></section>`;}
function quizSets(type,id){let s=subject(id),master=type==='master',a=state.attempts.find(a=>a.subject===s.id&&a.type===type&&!a.finished);let availableYears=pyqMcqYears(s.id);return page(`${top(s.name,master?'Syllabus Master Quiz / Set up':'PYQ MCQ Quiz / Choose paper')}${hero(s.short+' · '+(master?'MASTER QUIZ':'PYQ MCQ QUIZ'),master?'Ready for a challenge?':'Learn from past papers.',master?'Choose your units and focus time.':'Choose a paper year to begin.',master?'purple':'orange',master?'quiz':'paper')}${a?`<div class="card resume"><h3>You have an unfinished quiz</h3><p>Your answers and active time are saved.</p>${link('Resume quiz '+icon('arrow'),'/attempt/'+a.id,'button primary')}</div>`:''}${master?`<form id="quiz-setup" class="card form-card" data-subject="${s.id}"><h2>Make this session yours</h2><label>Units<select name="unit"><option value="all">All units</option>${s.units.map(u=>`<option value="${u.id}">Unit ${u.id} · ${u.title}</option>`).join('')}</select></label><label>Time limit<select name="minutes"><option value="10">10 minutes</option><option value="20" selected>20 minutes</option><option value="30">30 minutes</option><option value="0">No limit · elapsed timer</option></select></label><div class="notice"><span>${quizQuestions(s.id,'master').length} syllabus practice questions available across 6 units.</span></div><button class="primary full">Start master quiz ${icon('arrow')}</button></form>`:availableYears.length?`<div class="section-heading"><h2>Year-wise quiz sets</h2><span>Official papers</span></div>${availableYears.map((y,i)=>{let count=quizQuestions(s.id,'pyq',y).length;return `<article class="card paper-card"><div class="year-tile ${colors[i%colors.length]}">${icon('calendar')}<strong>${y}</strong></div><div><h2>${y} Paper</h2><p>Original BEU Question Paper</p><span class="badge orange">${count} original MCQs</span></div>${btn('Start quiz '+icon('arrow'),'start-pyq','button amber-button',`data-subject="${s.id}" data-year="${y}"`)}</article>`;}).join('')}`:`<div class="card empty"><span class="subject-icon orange">${icon('document')}</span><h3>Official Objective Papers Pending</h3><p>Official objective papers for ${s.name} were not present in the scanned bundle. Practice with the comprehensive 50-Question Master Mock instead.</p>${link('Start Master Mock '+icon('arrow'),'/quiz/master/'+s.id,'button primary')}</div>`}<div class="card notice">${icon('info')}<span>${master?'Answers and detailed explanations appear after submission.':'Original previous-year paper MCQs. Attempt under exam timing and review solutions.'}</span></div>${weightageSection(s.id)}`,{parent:'/quiz/'+type});}
function activeAttempt(){return state.attempts.find(a=>a.id===route()[1]);}
function startAttempt(s,type,year=null,unit='all',minutes=20,previousQuestions=null){let pool=quizQuestions(s,type,year);let questions=previousQuestions||(type==='master'?pool.filter(q=>unit==='all'||q.unit===+unit):pool);if(!questions.length){toast('No questions for this selection yet.');return;}let a={id:uid(),subject:s,type,year,questions,answers:questions.map(()=>null),times:questions.map(()=>0),index:0,startedAt:Date.now(),elapsed:0,limit:+minutes*60,finished:false};state.attempts.push(a);save();go('/attempt/'+a.id);}
function capture(){let a=activeAttempt();if(a&&!a.finished&&currentStart!==null){let now=Date.now();let delta=Math.max(0,(now-currentStart)/1000);a.times=recordTime(a.times,a.index,currentStart,now);a.elapsed+=delta;currentStart=now;save();}}
function quizScreen(a){if(!a)return page(top('Quiz not found')+'<p>Return to Quiz to start a new attempt.</p>',{parent:'/quiz'});if(a.finished){go('/result/'+a.id);return '';}let s=subject(a.subject),q=a.questions[a.index];return `<div class="app-shell quiz-shell"><main><header class="quiz-header"><span>${s.name}</span><span class="timer">${icon('clock')}<b id="timer">${time(a.limit?Math.max(0,a.limit-a.elapsed):a.elapsed)}</b></span></header><div class="quiz-toolbar">${btn(icon('grid')+' Questions '+(navigatorOpen?'⌃':'⌄'),'navigator','button outline','aria-expanded="'+navigatorOpen+'"')}${btn('Exit','exit','button exit')}</div>${navigatorOpen?`<section class="question-dropdown card"><div class="section-heading"><h3>Jump to question</h3>${btn(icon('close'),'navigator','round','aria-label="Close question navigator"')}</div><div class="number-grid">${a.questions.map((_,i)=>btn(String(i+1)+(a.answers[i]!=null?'<small>✓</small>':''),'jump','number '+(a.answers[i]!=null?'answered ':'')+(a.index===i?'current':''),`data-index="${i}" aria-label="Question ${i+1}${a.answers[i]!=null?', answered':''}"`)).join('')}</div><p class="muted small">✓ Answered · Purple outline = current</p></section>`:''}<section class="card active-question"><div class="question-flow-bar"><span class="badge ${colors[(q.unit-1)%colors.length]}">Unit ${q.unit} · ${s.units[q.unit-1]?.title || 'Syllabus'}</span><span class="flow-type-badge">${a.type==='master' ? 'Master Mock · Q'+(a.index+1)+' of '+a.questions.length : 'BEU '+a.year+' Exam · Q'+(a.index+1)}</span></div><h1>${esc(q.text)}</h1><div class="options">${q.options.map((o,i)=>btn(`<span class="radio"></span><span>${esc(o)}</span>`,'answer','option '+(a.answers[a.index]===i?'chosen':''),`data-value="${i}" role="radio" aria-checked="${a.answers[a.index]===i}"`)).join('')}</div></section><span class="quiz-demo">${a.type==='master'?'Syllabus Practice · Unit '+q.unit:'BEU '+a.year+' Exam · Question '+(a.index+1)}</span></main><div class="quiz-dock">${btn(icon('back')+' Back','previous','back-pill',a.index===0?'disabled':'')}${btn(a.index===a.questions.length-1?'Submit '+icon('check'):'Next '+icon('arrow'),a.index===a.questions.length-1?'submit-quiz':'next','next-pill')}</div></div>`;}
function finish(a){capture();a.finished=true;a.finishedAt=Date.now();currentStart=null;save();go('/result/'+a.id);}
function resultPage(id){let a=state.attempts.find(a=>a.id===id);if(!a)return page(top('Result not found'),{parent:'/history'});let s=subject(a.subject),r=scoreQuiz(a.questions,a.answers,a.times),status=r.score>=80?'Strong performance':r.score>=60?'Making progress':'Needs revision';let unitStats={};a.questions.forEach((q,i)=>{let u=q.unit||1;if(!unitStats[u])unitStats[u]={total:0,correct:0,wrong:0,skipped:0};unitStats[u].total++;if(a.answers[i]==null)unitStats[u].skipped++;else if(a.answers[i]===q.answer)unitStats[u].correct++;else unitStats[u].wrong++;});let masteryHtml=`<section class="card unit-mastery-card"><h2>Unit-Wise Concept Mastery</h2><p class="muted small">Analyze topic retention and identify high-yield areas for focused revision.</p><div class="unit-mastery-list">${Object.keys(unitStats).sort((x,y)=>+x-+y).map(u=>{let st=unitStats[u],pct=Math.round((st.correct/st.total)*100);let uTitle=s.units[u-1]?.title||'Unit '+u;let tagClass=pct>=80?'green':pct>=50?'orange':'coral';let tagText=pct>=80?'Mastered':pct>=50?'Needs Practice':'Critical Revision';return `<div class="unit-mastery-row"><div class="unit-mastery-meta"><span class="badge ${colors[(u-1)%colors.length]}">Unit ${u}</span><b>${esc(uTitle)}</b><span class="badge ${tagClass}">${tagText} · ${pct}%</span></div>${bar(pct,colors[(u-1)%colors.length])}<div class="flow-meta"><span>${st.correct} of ${st.total} correct (${st.wrong} wrong, ${st.skipped} skipped)</span>${pct<70?`<span class="revision-tip">Review: ${esc(unitWeightage[s.id]?.find(w=>w.unit===+u)?.flow?.split('→')[0]?.trim()||'Key definitions')}</span>`:''}</div></div>`;}).join('')}</div></section>`;return page(`${top('Quiz Results',s.name+' · '+(a.type==='master'?'Syllabus Master Quiz':a.year+' PYQ Paper Quiz'))}<section class="hero purple result-hero"><div><span class="eyebrow">QUIZ COMPLETED</span><h1>${r.correct} / ${r.total}</h1><h2>${r.score}% score</h2><span class="badge ${r.score>=80?'green':'coral'}">${status}</span><p>Every review is a step forward.</p></div><img class="result-art" src="./assets/quiz.png" alt="Quiz trophy"></section><div class="stat-grid"><div class="stat mint"><b>${r.correct}</b><span>Correct</span></div><div class="stat rose"><b>${r.wrong}</b><span>Wrong</span></div><div class="stat cream"><b>${r.skipped}</b><span>Skipped</span></div></div><section class="card"><h2>Time summary</h2><div class="two-stats"><div><p>Total active time</p><b>${time(r.totalSeconds)}</b></div><div><p>Average per question</p><b>${time(r.totalSeconds/r.total)}</b></div></div><p class="muted small">Includes revisits. Time away from the app is excluded.</p></section><section class="card"><h2>Performance snapshot</h2><div class="two-stats"><div><p>Attempt accuracy</p><b>${r.accuracy}%</b>${bar(r.accuracy,'purple')}</div><div><p>Completion</p><b>${Math.round(r.attempted/r.total*100)}%</b>${bar(r.attempted/r.total*100,'teal')}</div></div><p class="muted small">Status uses score: 80%+ strong, 60–79% making progress, below 60% needs revision. Speed alone does not determine performance.</p></section>${masteryHtml}<div class="section-heading"><h2>Question-by-question review</h2></div><div class="chips">${[['all',`All (${r.total})`],['correct',`Correct (${r.correct})`],['wrong',`Wrong (${r.wrong})`],['skipped',`Skipped (${r.skipped})`]].map(([v,t])=>btn(t,'result-filter','chip '+(resultFilter===v?'selected purple-button':''),`data-value="${v}"`)).join('')}</div><div id="reviews">${a.questions.map((q,i)=>{let status=a.answers[i]==null?'skipped':a.answers[i]===q.answer?'correct':'wrong';if(resultFilter!=='all'&&resultFilter!==status)return '';return `<article class="card review"><div class="review-meta"><span class="badge purple">Q${i+1}</span><span class="badge ${status==='correct'?'green':status==='wrong'?'coral':'orange'}">${status}</span><span class="time-chip">${icon('clock')}${time(a.times[i])}</span></div><h3>${esc(q.text)}</h3><div class="answer-review"><div class="${status==='correct'?'mint':status==='wrong'?'rose':'cream'}"><small>Your answer</small><b>${a.answers[i]==null?'Not answered':esc(q.options[a.answers[i]])}</b></div><div class="mint"><small>Correct answer</small><b>${esc(q.options[q.answer])}</b></div></div><p class="explanation"><b>Explanation:</b> ${esc(q.explanation)}</p></article>`;}).join('')}</div><div class="action-row">${btn('Save & return to quizzes','save-result','button purple-button',`data-id="${a.id}"`)}${btn('Retry quiz','retry','button outline',`data-id="${a.id}"`)}</div>`,{parent:`/quiz/${a.type}/${a.subject}`});}
function taskRow(t){return `<div class="task-row"><input aria-label="Mark ${esc(t.title)} complete" type="checkbox" data-task="${t.id}" ${t.status==='done'?'checked':''}><div><h3>${esc(t.title)}</h3><p>${subject(t.subject).short} · ${t.minutes} min · ${formatDate(t.date)}</p></div>${t.status==='done'?'<span class="badge green">Done</span>':btn(icon('close'),'miss-task','round',`data-id="${t.id}" aria-label="Mark task missed"`)}</div>`;}
function planner(){let tasks=state.tasks.filter(t=>planFilter==='all'||(planFilter==='today'?t.date===dateKey():t.status==='missed'));return page(`${top('Preparation Planner','Small plans. Steady progress.')}${hero('MAKE TIME FOR WHAT MATTERS','Your path to exam day.','Plan a little. Learn a little. Every day.','blue')}<section class="card"><div class="section-heading"><h2>Exam schedule</h2></div><p class="small muted schedule-meta">All papers · ${examSession.label} IST</p><ol class="exam-schedule">${examSchedule.map(e=>{let sub=subject(e.subject),past=e.date<dateKey();return `<li class="exam-schedule-row"><span class="schedule-date ${sub.color}"><b>${new Date(e.date+'T12:00:00').getDate()}</b><small>${new Date(e.date+'T12:00:00').toLocaleDateString('en-IN',{month:'short'})}</small></span><div><span class="badge ${sub.color}">${sub.short}</span><h3>${sub.name}</h3><p><time datetime="${e.date}">${new Date(e.date+'T12:00:00').toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'short',year:'numeric'})}</time>${past?' · Completed':e.date===dateKey()?' · Today':''}</p></div></li>`;}).join('')}</ol><a href="${examSession.source}" class="text-link" target="_blank" rel="noopener">View official routine ${icon('arrow')}</a></section><section class="card"><h2>Your study plan</h2><p>Build 30-minute topic sessions around your availability and nearest exams.</p><div class="action-row">${btn('Build / refresh plan','generate-plan','button primary')}${link('Study preferences','/preferences','button outline')}</div><label class="toggle-row">Automatically reschedule pending work<input type="checkbox" id="auto-plan" ${state.settings.autoPlan?'checked':''}></label><p class="small muted">Completed tasks stay in your history. Missed tasks can be rescheduled.</p></section><form id="task-form" class="card form-card"><h2>Add a study task</h2><label>Task<input name="title" required maxlength="180" placeholder="e.g. Revise subnetting"></label><div class="form-grid"><label>Subject<select name="subject">${subjects.map(s=>`<option value="${s.id}">${s.short}</option>`).join('')}</select></label><label>Date<input name="date" type="date" required value="${dateKey()}"></label></div><button class="outline full">Add task</button></form><div class="chips">${[['today','Today'],['all','All tasks'],['missed','Missed']].map(([v,t])=>btn(t,'plan-filter','chip '+(planFilter===v?'selected':''),`data-value="${v}"`)).join('')}</div><section class="card task-list">${tasks.map(taskRow).join('')||'<div class="empty"><h3>Your plan is clear.</h3><p>Add a task or generate a study plan.</p></div>'}</section>`,{parent:'/home'});}
function regenerate(){let used=new Set(state.tasks.filter(t=>t.status==='done'||!t.auto).map(t=>t.topic));state.tasks=state.tasks.filter(t=>t.status==='done'||!t.auto);state.tasks.push(...buildPlan(allTopics.filter(t=>!used.has(t.id)),state.topics,dateKey(),state.settings.availability,examDates));save();}
function profileFooter(){const socialIcons={website:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a18 18 0 0 1 0 18 18 18 0 0 1 0-18Z"/>',linkedin:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M7.5 10v7M7.5 7v.1M11 17v-7m0 3a3 3 0 0 1 6 0v4"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m4 7 8 6 8-6"/>'};return `<footer class="profile-footer"><h2 id="follow-heading">Follow us on</h2><nav class="social-links" aria-labelledby="follow-heading">${[['website','Website'],['linkedin','LinkedIn'],['mail','Mail']].map(([id,label])=>{const content=`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${socialIcons[id]}</svg><span>${label}</span>`;return socialLinks[id]?`<a class="social-link" href="${esc(socialLinks[id])}" ${id!=='mail'?'target="_blank" rel="noopener noreferrer"':''}>${content}</a>`:`<button class="social-link" type="button" disabled aria-label="${label} — coming soon">${content}</button>`;}).join('')}</nav><p class="app-version" title="Build ${esc(buildId)}">v${esc(appVersion)}</p><div class="brand-signature"><p class="brand-shimmer">BEU Exam Dost</p><p class="brand-shimmer brand-byline">By BEU Developer</p></div></footer>`;}
function isPwaActive(){try{return(typeof window!=='undefined'&&(window.matchMedia?.('(display-mode: standalone)').matches||window.navigator.standalone===true||document.referrer.includes('android-app://')||localStorage.getItem('pwa_installed')==='true'));}catch{return false;}}
function showInstallSheet(){if(isPwaActive()){toast('You are already using the BEU Exam Dost PWA app!');return;}const existing=document.getElementById('install-sheet-wrap');if(existing)existing.remove();const wrap=document.createElement('div');wrap.id='install-sheet-wrap';wrap.className='install-sheet-backdrop active';wrap.innerHTML=`<div class="install-bottom-sheet"><div class="sheet-drag-handle"></div><div class="sheet-header"><img src="./assets/icon-192.png" alt="BEU Exam Dost"><div><h3>Install BEU Exam Dost</h3><p>Instant Offline Study Companion · Free PWA</p></div></div><div class="sheet-steps"><div class="sheet-step"><span class="sheet-step-badge">1</span><div><strong>Fast 1-Tap Offline Access:</strong> All syllabus topics, 7-mark PYQs, and exam schedule stay saved on your device.</div></div><div class="sheet-step"><span class="sheet-step-badge">2</span><div><strong>On Android (Chrome / Brave / Edge):</strong> Tap “Install App Now” below or tap browser menu (⋮) → “Add to Home screen”.</div></div><div class="sheet-step"><span class="sheet-step-badge">3</span><div><strong>On iPhone (Safari):</strong> Tap the Share button [↑] at the bottom bar → scroll and tap “Add to Home Screen”.</div></div></div><div class="sheet-actions"><button class="primary full" id="sheet-install-action">Install App Now ${icon('download')}</button><button class="outline full" id="sheet-dismiss-action">Maybe Later</button></div></div>`;document.body.appendChild(wrap);wrap.querySelector('#sheet-dismiss-action').onclick=()=>wrap.remove();wrap.onclick=e=>{if(e.target===wrap)wrap.remove();};wrap.querySelector('#sheet-install-action').onclick=()=>{if(installPrompt){installPrompt.prompt();installPrompt.userChoice.then(c=>{if(c&&c.outcome==='accepted'){localStorage.setItem('pwa_installed','true');toast('✓ BEU Exam Dost PWA installing!');wrap.remove();render();}installPrompt=null;});}else{toast('Tap your browser menu (⋮ or Share) and select “Add to Home screen”.');}};}
function checkDesktopNotice(){if(typeof window==='undefined')return;if(window.innerWidth>860&&!sessionStorage.getItem('desktop_gate_seen')){const existing=document.getElementById('desktop-gate');if(!existing){const gate=document.createElement('div');gate.id='desktop-gate';gate.className='desktop-gate-overlay';gate.innerHTML=`<div class="desktop-gate-card"><div class="desktop-gate-badge">${icon('phone')} Mobile-First Experience</div><h2>Configured for Mobile Devices</h2><p><strong>BEU Exam Dost</strong> is crafted exclusively as a mobile Progressive Web App (PWA) to provide Bihar Engineering University students with an offline-first, fast touch study companion.</p><div class="desktop-gate-qr-box">${icon('phone')}<div><b>Desktop & Laptop Version Coming Soon!</b><small>We are actively building the dedicated desktop experience. For the intended UI and study flow, please open on your smartphone or install the PWA.</small></div></div><p class="muted small">Mobile Web App: <a href="https://app.beudeveloper.in/" target="_blank" rel="noopener" style="text-decoration:underline;color:inherit;font-weight:600">https://app.beudeveloper.in/</a><br>Main Project Portal: <a href="https://beudeveloper.in/" target="_blank" rel="noopener" style="text-decoration:underline;color:inherit;font-weight:600">https://beudeveloper.in/</a></p><div class="desktop-gate-actions"><button class="primary full" id="gate-copy-btn">Copy Mobile App Link ${icon('check')}</button><button class="outline full" id="gate-continue-btn">Continue in Mobile Preview Frame ${icon('arrow')}</button></div></div>`;document.body.appendChild(gate);gate.querySelector('#gate-copy-btn').onclick=()=>{navigator.clipboard?.writeText('https://app.beudeveloper.in/').then(()=>toast('Link copied! Open on your smartphone.'));};gate.querySelector('#gate-continue-btn').onclick=()=>{sessionStorage.setItem('desktop_gate_seen','true');gate.remove();};}}}
function profile(){let p=percent(allTopics),done=state.attempts.filter(a=>a.finished),avg=done.length?Math.round(done.reduce((n,a)=>n+scoreQuiz(a.questions,a.answers,a.times).score,0)/done.length):0;let isPwa=isPwaActive();return page(`${top('My Profile')}<section class="profile-hero lavender"><span class="avatar">${profileInitial()}</span><div><h1>${esc(state.profile.name)}</h1><p>${esc(state.profile.college)}</p><p>${esc(state.profile.branch)}</p><div class="chips"><span class="badge green">2024–28</span><span class="badge purple">Semester 4</span></div>${link('Edit profile','/edit-profile','button outline')}</div></section><div class="section-heading"><h2>Your preparation</h2></div><div class="stat-grid"><div class="stat mint"><b>${p.pct}%</b><span>Syllabus</span></div><div class="stat lavender"><b>${done.length}</b><span>Quizzes</span></div><div class="stat cream"><b>${avg}%</b><span>Avg. score</span></div></div><section class="card settings-list"><h2>Preferences</h2>${row('Study preferences','Daily availability & study goal','/preferences','settings','coral')}<div class="settings-row appearance-row">${icon('sun')}<span>Appearance</span><div class="theme-control"><span class="theme-label ${state.settings.theme==='light'?'is-selected':''}" aria-hidden="true">Light</span>${btn('<span class="theme-thumb"></span>','theme','theme-switch',`role="switch" aria-label="Dark mode" aria-checked="${state.settings.theme==='dark'}"`)}<span class="theme-label ${state.settings.theme==='dark'?'is-selected':''}" aria-hidden="true">Dark</span></div></div>${row('Study reminders','See today’s tasks in the app','/reminders','bell','green')}${row('Quiz history','Results & unfinished attempts','/history','clock','purple')}</section><section class="card settings-list"><h2>Your data</h2>${btn(icon('upload')+'<span>Export backup</span>'+icon('chevron'),'export','settings-row')}${btn(icon('download')+'<span>Import backup</span>'+icon('chevron'),'import','settings-row')}</section><section class="card settings-list"><h2>PWA App Status</h2>${isPwa?`<div class="settings-row pwa-active-row"><span class="mini-icon green">${icon('check')}</span><span><b>Using BEU Exam Dost PWA App</b><small>Active on this device · Fast offline mode enabled</small></span><span class="badge green">PWA Active</span></div>`:`${row('Download BEU Exam Dost PWA','Install app on your phone for instant offline study','/install','download','orange')}`}</section><section class="card settings-list"><h2>About & Legal</h2>${row('About BEU Exam Dost','Mission, offerings & developer notes','/about','info','green')}${row('Privacy Policy','Data usage, local storage & AI disclaimer','/privacy','shield','purple')}${row('Terms & Conditions','Rules, liability & university disclaimer','/terms','document','blue')}</section>${profileFooter()}`,{parent:'/home'});}
function row(title,sub,path,ic,tone){return link(`<span class="mini-icon ${tone}">${icon(ic)}</span><span>${title}<small>${sub}</small></span>${icon('chevron')}`,path,'settings-row');}
function preferences(){return page(`${top('Study preferences','A routine that works for you')}<form id="preferences-form" class="card form-card"><h2>One primary goal</h2><label>My focus<select name="goal">${['Complete important topics','Revise the full syllabus','Improve MCQ accuracy','Focus on important PYQs'].map(g=>`<option ${state.settings.goal===g?'selected':''}>${g}</option>`).join('')}</select></label><h2>Daily availability</h2><p>Choose a separate study duration for every day.</p>${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((d,i)=>`<label class="availability">${d}<select name="day${i}">${[0,30,60,90,120,180,240].map(n=>`<option value="${n}" ${+state.settings.availability[i]===n?'selected':''}>${n===0?'Day off':n+' minutes'}</option>`).join('')}</select></label>`).join('')}<label>Preferred study slot<select name="slot">${['Morning','Afternoon','Evening'].map(v=>`<option ${state.settings.slot===v?'selected':''}>${v}</option>`).join('')}</select></label><button class="primary full">Save preferences</button></form>`,{parent:'/profile'});}
function historyPage(){return page(`${top('Quiz history','Your progress, one attempt at a time')}${state.attempts.length?[...state.attempts].reverse().map(a=>link(`<span class="subject-icon ${a.finished?'purple':'orange'}">${icon(a.finished?'trophy':'clock')}</span><div><h3>${subject(a.subject).short} · ${a.type==='master'?'Master Quiz':a.year+' Paper'}</h3><p>${a.finished?scoreQuiz(a.questions,a.answers,a.times).score+'% · Completed':'Saved · Resume attempt'}</p><small>${new Date(a.startedAt).toLocaleDateString('en-IN')}</small></div>${icon('chevron')}`,(a.finished?'/result/':'/attempt/')+a.id,'card history-card')).join(''):'<div class="card empty"><h2>Your first quiz is waiting.</h2><p>Completed results and saved attempts appear here.</p>'+link('Explore quizzes','/quiz','button purple-button')+'</div>'}`,{parent:'/profile'});}
function installPage(){let isPwa=isPwaActive();return page(`${top('Install BEU Exam Dost','Your study companion, one tap away')}${hero('TAKE YOUR STUDY WITH YOU','A little closer.<br>A little easier.','Choose how you want to use BEU Exam Dost.','blue','phone')}${isPwa?`<section class="card mode-card green"><span class="badge green">INSTALLED & ACTIVE</span><h2>Using the PWA App</h2><p>BEU Exam Dost is successfully running as an installed Progressive Web App on your device. All question papers, syllabus checklists, and exam schedules are cached locally.</p><div class="mode-features">✓ Fullscreen Experience · ✓ 100% Offline Ready · ✓ Zero App Store Needed</div></section>`:`<section class="card mode-card green"><span class="badge green">RECOMMENDED</span><h2>Install as PWA</h2><p>Add BEU Exam Dost to your home screen directly from your browser for instant offline access.</p><div class="mode-features">Offline study content · Fullscreen · No account needed</div>${btn('Download & Install PWA '+icon('download'),'show-install-sheet','button primary full')}`}<section class="card mode-card purple"><span class="badge green">AVAILABLE</span><h2>Android APK</h2><p>Download the standalone native Android APK package (9.5 MB) for direct installation.</p><a class="button outline full" href="/new-exam-dost.apk" download="new-exam-dost.apk">Download Android APK (9.5 MB)</a></section><div class="card notice">${icon('info')}<span>Open online once to ensure assets are fully cached offline. Installation is supported across Android Chrome, Samsung Internet, Edge, and iOS Safari.</span></div><p id="offline-status" class="footnote">${navigator.onLine?'You’re online':'You’re offline'}</p>`,{parent:'/profile'});}
function privacy(){return page(`${top('Privacy Policy','BEU Exam Dost')}<article class="card legal-document"><div class="legal-header"><span class="badge purple">LEGAL POLICY</span><h1>Privacy Policy</h1><p class="legal-meta"><strong>BEU Exam Dost</strong><br>By BEU Developer<br><strong>Last Updated:</strong> 23 October 2026</p></div><h2>1. About BEU Exam Dost</h2><p>BEU Exam Dost is an independent educational Progressive Web App (PWA) developed by BEU Developer to help Bihar Engineering University (BEU) students prepare for their examinations.</p><p>Our app provides previous-year questions (PYQs), study notes, AI-assisted solutions, practice tests, study planning, and progress tracking.</p><p>The app is created for educational assistance only.</p><h2>2. Information We Use</h2><p>To provide personalized features, BEU Exam Dost may use basic information such as:</p><ul><li>Name and academic details provided by students.</li><li>Selected subjects and study preferences.</li><li>Study plans, completed tasks, and learning progress.</li><li>Practice test scores and performance records.</li><li>Bookmarked questions and saved preferences.</li></ul><p>Some information may be stored in your browser to keep app features working properly.</p><p>We use this information to support your learning experience, not for selling personal data.</p><h2>3. AI-Generated Solutions</h2><div class="legal-alert"><p><strong>Important: Please read before using our study materials.</strong></p><p>Some answers, explanations, and solutions available on BEU Exam Dost are prepared with the assistance of Artificial Intelligence (AI).</p><p>While we aim to provide helpful and understandable solutions, AI can make mistakes.</p></div><p>Therefore:</p><ul><li>Some answers may contain incorrect information or calculations.</li><li>Explanations may occasionally be incomplete.</li><li>Solutions may differ from answers expected by university examiners.</li><li>We do not guarantee that every answer is 100% accurate.</li><li>Students should verify important answers using textbooks, teachers, and official study materials.</li></ul><p><strong>BEU Exam Dost and BEU Developer are not responsible for incorrect AI-generated answers or academic consequences resulting from relying on them, to the extent permitted by applicable law.</strong></p><h2>4. Previous-Year Questions and Study Materials</h2><p>We provide PYQs, notes, and other educational resources to help students prepare for examinations.</p><p>We try to keep these materials useful and relevant. However, we cannot guarantee that every question, solution, or document is completely accurate, updated, or free from errors.</p><p>Students should refer to official university announcements and resources for confirmed examination information.</p><h2>5. Study Planner and Progress Tracking</h2><p>BEU Exam Dost includes study planning and progress tracking features to help students organize their preparation.</p><p>Study schedules, suggestions, progress percentages, and preparation insights are intended as guidance only.</p><p>They do not guarantee specific marks, examination results, or academic success.</p><h2>6. App Data and Local Storage</h2><p>BEU Exam Dost may use browser storage and caching to save preferences, improve loading speed, and support PWA functionality.</p><p>Clearing browser data, uninstalling the PWA, or changing devices may remove some locally saved information.</p><p>We cannot guarantee the recovery of deleted or unsynchronized local data.</p><h2>7. External Links</h2><p>Our app may contain links to external educational resources and websites.</p><p>We are not responsible for the content, accuracy, or privacy practices of those external websites.</p><h2>8. Independent Educational Platform</h2><p>BEU Exam Dost is developed and managed independently by BEU Developer.</p><p><strong>It is not an official application of Bihar Engineering University (BEU), nor is it affiliated with or endorsed by the university.</strong></p><p>The university's name is used only to identify the academic context for which the app provides learning resources.</p><h2>9. Limitation of Responsibility</h2><p>BEU Exam Dost is provided as an educational support tool.</p><p>BEU Exam Dost and BEU Developer do not guarantee:</p><ul><li>Completely error-free answers or study materials.</li><li>Any specific examination marks or results.</li><li>Uninterrupted app availability.</li><li>Complete accuracy of AI-generated explanations.</li><li>Recovery of locally deleted app data.</li></ul><p>Users are responsible for independently verifying academic information before relying on it.</p><p>To the extent permitted by applicable law, BEU Exam Dost and BEU Developer are not liable for academic losses or other consequences resulting from inaccurate study content or technical issues.</p><h2>10. Updates to This Policy</h2><p>We may update this Privacy Policy when BEU Exam Dost features or practices change.</p><p>The updated version will be published within the application.</p><h2>11. Contact</h2><p>For questions, feedback, or reporting incorrect content, users may contact BEU Developer through the official contact channel provided in the app.</p><div class="legal-footer"><p><strong>Disclaimer:</strong> BEU Exam Dost is an independent educational project. AI-assisted solutions may contain mistakes. Always verify answers before using them for examination preparation.</p><p><strong>© 2026 BEU Developer. All Rights Reserved.</strong></p></div></article>`,{parent:state.profile?'/profile':'/setup'});}
function about(){return page(`${top('About BEU Exam Dost','Your Exam Companion')}<article class="card legal-document"><div class="legal-header"><span class="badge green">ABOUT US</span><h1>About BEU Exam Dost</h1><p class="legal-tagline"><strong>Your Companion for BEU Exam Success</strong></p></div><p><strong>BEU Exam Dost</strong> is an independent educational Progressive Web App (PWA), developed by <strong>BEU Developer</strong>, to make examination preparation easier, more organized, and accessible for students of Bihar Engineering University (BEU).</p><p>We understand that students often need to manage multiple subjects, find previous-year questions, prepare reliable notes, and complete their syllabus within limited time.</p><p>BEU Exam Dost brings useful preparation resources and study tools together in one place.</p><h2>What We Offer</h2><h3>Previous-Year Questions (PYQs)</h3><p>Explore previous-year examination questions to understand question patterns, important topics, and examination requirements.</p><h3>AI-Assisted Solutions</h3><p>Access detailed explanations and solutions prepared with the assistance of Artificial Intelligence to support learning and revision.</p><h3>Subject-Wise Preparation</h3><p>Organize preparation through subjects, units, topics, and relevant educational resources.</p><h3>Smart Study Planner</h3><p>Create and manage personalized study schedules, daily tasks, and preparation goals.</p><h3>Practice Tests</h3><p>Evaluate understanding through practice questions and tests designed for examination preparation.</p><h3>Progress Tracking</h3><p>Monitor completed tasks, preparation progress, and practice performance to identify areas that need more attention.</p><h2>Our Mission</h2><p>Our mission is simple:</p><p style="font-size:16px;font-weight:600;color:var(--forest,#15864c)">“To make BEU examination preparation more accessible, structured, and less stressful for students.”</p><p>We aim to help students spend less time searching for study resources and more time understanding concepts, practicing questions, and preparing confidently.</p><h2>Built for Students</h2><p>BEU Exam Dost is designed with the everyday needs of engineering students in mind.</p><p>Whether you are revising a unit, solving previous-year questions, or planning your next study session, the app aims to make your preparation more manageable.</p><h2>Important Note</h2><p>Some solutions and explanations are created using AI and may contain mistakes. Students should verify important academic information using textbooks, teachers, and official university resources.</p><p><strong>BEU Exam Dost is an independent educational project and is not an official application of, affiliated with, or endorsed by Bihar Engineering University.</strong></p><div class="legal-footer"><p><strong>BEU Exam Dost</strong><br><em>Same Notes. Same Dreams. Stronger Together.</em><br>Developed by <strong>BEU Developer</strong></p><p><strong>© 2026 BEU Developer. All Rights Reserved.</strong></p></div></article>`,{parent:state.profile?'/profile':'/setup'});}
function terms(){return page(`${top('Terms & Conditions','User Agreement')}<article class="card legal-document"><div class="legal-header"><span class="badge blue">TERMS & CONDITIONS</span><h1>Terms & Conditions</h1><p class="legal-meta"><strong>BEU Exam Dost — By BEU Developer</strong><br><strong>Last Updated:</strong> 23 October 2026</p></div><p>Welcome to BEU Exam Dost. These Terms & Conditions explain the basic rules and limitations of using our educational application.</p><p>By using BEU Exam Dost, you agree to these terms.</p><h2>1. Purpose of the App</h2><p>BEU Exam Dost is an independent educational platform designed to help Bihar Engineering University students with examination preparation.</p><p>The app provides previous-year questions, study notes, AI-assisted solutions, practice tests, study planning, and progress tracking.</p><p>All resources are intended for educational and personal study purposes.</p><h2>2. AI-Generated Solutions and Accuracy</h2><div class="legal-alert"><p><strong>Important Disclaimer</strong></p><p>Some answers, explanations, and educational solutions available on BEU Exam Dost are prepared using Artificial Intelligence (AI).</p><p>AI-generated content may contain mistakes, including incorrect calculations, incomplete explanations, or inaccurate information.</p></div><p>Please understand that:</p><ul><li>We do not guarantee 100% accuracy of AI-assisted solutions.</li><li>Answers may differ from university-approved or examiner-expected solutions.</li><li>Some educational information may be incomplete or outdated.</li><li>Students should verify important answers using textbooks, teachers, or official resources.</li></ul><p><strong>BEU Exam Dost and BEU Developer are not responsible for incorrect AI-generated solutions or resulting academic consequences, including loss of marks or examination performance, to the extent permitted by applicable law.</strong></p><p>Students use these solutions at their own discretion.</p><h2>3. Previous-Year Questions and Study Materials</h2><p>Previous-year questions, notes, and other study materials are provided to assist examination preparation.</p><p>We try to present relevant information, but we cannot guarantee that every question, document, or solution is completely accurate or up to date.</p><p>BEU Exam Dost does not guarantee that any particular question will appear in an upcoming examination.</p><p>For confirmed syllabi, exam schedules, results, and official announcements, students should refer to Bihar Engineering University's official communications.</p><h2>4. Study Planner and Practice Tests</h2><p>The study planner, preparation percentages, practice scores, and learning recommendations are designed to help students organize their studies.</p><p>These features provide estimates and guidance based on available information and user activity.</p><p>They do not guarantee examination success, passing marks, or any specific academic result.</p><h2>5. Responsible Use</h2><p>Users are expected to use BEU Exam Dost for legitimate educational purposes.</p><p>Users should not:</p><ul><li>Attempt to damage, disrupt, or misuse the application.</li><li>Access other users' accounts or information without permission.</li><li>Submit harmful or abusive content through app features.</li><li>Misrepresent BEU Exam Dost as an official university service.</li></ul><p>We may restrict access to features where reasonably necessary to prevent misuse.</p><h2>6. Educational Content and Ownership</h2><p>BEU Exam Dost may contain educational materials, previous-year questions, explanatory content, and references to third-party resources.</p><p>Original app design, branding, and developer-created content belong to BEU Developer, except where otherwise stated.</p><p>University names, trademarks, and third-party materials belong to their respective owners.</p><p>Users may use available study resources for personal educational purposes, subject to any applicable third-party rights.</p><h2>7. App Availability and Saved Data</h2><p>We aim to keep BEU Exam Dost accessible and functional, but temporary errors, maintenance, or technical interruptions may occur.</p><p>Certain preferences and learning information may be stored locally in the user's browser.</p><p>Clearing browser storage, uninstalling the PWA, or changing devices may result in loss of locally saved or unsynchronized information.</p><p>We cannot guarantee uninterrupted availability or recovery of deleted local data.</p><h2>8. No Official University Affiliation</h2><p><strong>BEU Exam Dost is not an official application of Bihar Engineering University.</strong></p><p>It is independently developed and maintained by BEU Developer.</p><p>The application is not affiliated with, authorized by, or endorsed by Bihar Engineering University.</p><p>References to BEU, academic subjects, and examinations are provided for educational identification purposes only.</p><h2>9. Limitation of Liability</h2><p>BEU Exam Dost is provided as an educational assistance tool.</p><p>We make reasonable efforts to provide useful learning resources, but we do not guarantee that all content and features will be accurate, complete, or error-free.</p><p>To the maximum extent permitted by applicable law, BEU Exam Dost and BEU Developer will not be liable for academic losses, incorrect answers, examination results, or other consequences resulting from reliance on educational content or app technical issues.</p><p>Nothing in these Terms excludes rights or responsibilities that cannot legally be excluded.</p><h2>10. Changes to the App and Terms</h2><p>We may update, improve, modify, or discontinue app features as the project develops.</p><p>These Terms & Conditions may also be updated when necessary.</p><p>The latest version will be made available within the application, with its updated revision date.</p><h2>11. Privacy</h2><p>Information about how BEU Exam Dost handles user information and app storage is available in our separate <strong>Privacy Policy</strong>.</p><p>Users are encouraged to read that policy to understand the application's data practices.</p><h2>12. Contact and Feedback</h2><p>If you find an incorrect solution, broken feature, or other issue, you can report it through the official contact or feedback channel provided within BEU Exam Dost.</p><p>We welcome constructive suggestions that help improve the platform.</p><div class="legal-footer"><p><strong>Final Disclaimer:</strong> BEU Exam Dost is an independent educational assistance platform. AI-generated solutions may contain errors. Students are responsible for verifying academic information before relying on it. BEU Exam Dost and BEU Developer do not guarantee examination results and disclaim responsibility for inaccuracies and their consequences to the extent permitted by applicable law.</p><p><strong>BEU Exam Dost</strong><br>Developed by <strong>BEU Developer</strong></p><p><strong>© 2026 BEU Developer. All Rights Reserved.</strong></p></div></article>`,{parent:state.profile?'/profile':'/setup'});}
function reminders(){let t=state.tasks.filter(t=>t.date<=dateKey()&&t.status==='pending');return page(`${top('Study reminders','Your next small step')}<div class="card notice">${icon('bell')}<span>In-app reminders only. Background push notifications are not connected.</span></div><section class="card task-list">${t.map(taskRow).join('')||'<div class="empty">You’re all caught up. Add your next task in the planner.</div>'}</section>${link('Open planner','/planner','button primary')}`,{parent:'/home'});}
function formatDate(v){return new Date(v+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'});}function time(n){n=Math.max(0,Math.floor(n||0));return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function render(){let r=route();document.documentElement.dataset.theme=state.settings.theme;checkDesktopNotice();let html;if(!state.profile&&!['privacy','about','terms'].includes(r[0]))html=setup();else switch(r[0]){case 'setup':html=state.profile?home():setup();break;case 'edit-profile':html=setup(true);break;case 'subjects':html=r[2]?unitPage(r[1],r[2]):r[1]?subjectPage(r[1]):subjectsPage();break;case 'pyqs':html=r[1]?pyqSubject(r[1]):pyqIndex();break;case 'quiz':html=r[2]?quizSets(r[1],r[2]):r[1]?quizSubjects(r[1]):quizIndex();break;case 'attempt':html=quizScreen(activeAttempt());break;case 'result':html=resultPage(r[1]);break;case 'planner':html=planner();break;case 'profile':html=profile();break;case 'preferences':html=preferences();break;case 'history':html=historyPage();break;case 'install':html=installPage();break;case 'privacy':html=privacy();break;case 'about':html=about();break;case 'terms':html=terms();break;case 'reminders':html=reminders();break;default:html=home();}$('#app').innerHTML=html;const titles={privacy:'Privacy Policy · BEU Exam Dost',about:'About BEU Exam Dost · BEU Developer',terms:'Terms & Conditions · BEU Exam Dost',install:'Install BEU Exam Dost PWA',planner:'BEU 4th Sem Exam Routine & Routine Tracker · BEU Exam Dost',profile:'My Profile · BEU Exam Dost',history:'Quiz Performance History · BEU Exam Dost',preferences:'Study Preferences · BEU Exam Dost',reminders:'Study Reminders · BEU Exam Dost'};if(r[0]==='subjects')document.title=(r[1]?subject(r[1]).name+(r[2]?' Unit '+r[2]:'')+' Syllabus & Notes':'BEU 4th Sem CSE Subjects & Notes')+' · BEU Exam Dost';else if(r[0]==='pyqs')document.title=(r[1]?subject(r[1]).name+' PYQ & 7-Mark Questions':'BEU 4th Sem CSE PYQ Question Banks')+' · BEU Exam Dost';else if(r[0]==='quiz')document.title=(r[2]?subject(r[2]).name+' Objective MCQ Quiz':'BEU 4th Sem CSE Practice Quizzes & MCQs')+' · BEU Exam Dost';else if(titles[r[0]])document.title=titles[r[0]];else document.title='BEU 4th Sem CSE PYQ, Notes, Syllabus | BEU Exam Dost';}
function dialog(title,body,actions){let m=$('#modal');m.innerHTML=`<div class="dialog-inner"><h2>${title}</h2><p>${body}</p><div class="dialog-actions">${actions}</div></div>`;m.showModal();}
function closeDialog(){$('#modal').close();}
// External link handler: force external URLs to open in system browser when in PWA standalone mode
document.addEventListener('click',e=>{let anchor=e.target.closest('a[href]');if(anchor){let href=anchor.getAttribute('href');if(href&&(href.startsWith('http')||href.startsWith('mailto'))){try{let url=new URL(href);if(url.origin!==location.origin){e.preventDefault();window.open(href,'_blank','noopener,noreferrer');}}catch(_){}}};let el=e.target.closest('[data-action]');if(!el)return;let a=activeAttempt();switch(el.dataset.action){case'reminders':go('/reminders');break;case'unit-filter':unitFilter=el.dataset.value;render();break;case'pyq-kind':pyqKind=el.dataset.kind;render();break;case'saved-filter':savedOnly=!savedOnly;render();break;case'toggle-solution':{let id=el.dataset.id;if(openSolutions.has(id))openSolutions.delete(id);else openSolutions.add(id);let y=window.scrollY;render();window.scrollTo(0,y);break;}case'mark':case'save-question':{let arr=el.dataset.action==='mark'?state.marked:state.saved;let id=el.dataset.id,i=arr.indexOf(id);i<0?arr.push(id):arr.splice(i,1);save();render();break;}case'generate-plan':regenerate();render();toast('Study plan refreshed around your availability.');break;case'plan-filter':planFilter=el.dataset.value;render();break;case'miss-task':{let t=state.tasks.find(t=>t.id===el.dataset.id);t.status='missed';if(state.settings.autoPlan)regenerate();save();render();break;}case'start-pyq':startAttempt(el.dataset.subject,'pyq',+el.dataset.year,'all',10);break;case'practice-unit':startAttempt(el.dataset.subject,'master',null,+el.dataset.unit,15);break;case'navigator':navigatorOpen=!navigatorOpen;render();break;case'answer':capture();a.answers[a.index]=+el.dataset.value;save();render();break;case'jump':case'next':case'previous':capture();a.index=el.dataset.action==='jump'?+el.dataset.index:Math.max(0,Math.min(a.questions.length-1,a.index+(el.dataset.action==='next'?1:-1)));navigatorOpen=false;save();render();break;case'exit':capture();currentStart=null;dialog('Save and leave this quiz?','Your answers and active time will stay on this device. Resume when you’re ready.',btn('Keep studying','cancel','button outline')+btn('Save & exit','confirm-exit','button primary'));break;case'confirm-exit':closeDialog();save();go(`/quiz/${a.type}/${a.subject}`);break;case'cancel':closeDialog();if(a&&!a.finished)currentStart=Date.now();break;case'submit-quiz':capture();currentStart=null;dialog('Submit your quiz?',`${a.answers.filter(v=>v==null).length} unanswered question(s) will count as skipped.`,btn('Go back','cancel','button outline')+btn('Submit quiz','confirm-submit','button purple-button'));break;case'confirm-submit':closeDialog();finish(a);break;case'result-filter':resultFilter=el.dataset.value;render();break;case'save-result':save();if(storageOK){resultFilter='all';go('/quiz');toast('Quiz result saved.');}break;case'retry':{let old=state.attempts.find(a=>a.id===el.dataset.id);startAttempt(old.subject,old.type,old.year,'all',old.limit/60,old.questions);break;}case'theme':state.settings.theme=state.settings.theme==='dark'?'light':'dark';save();render();$('.theme-switch')?.focus({preventScroll:true});break;case'export':{capture();let blob=new Blob([JSON.stringify({app:'exam-dost',version:1,state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download='exam-dost-backup-'+dateKey()+'.json';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Backup exported. Keep it safe.');break;}case'import':{let f=document.createElement('input');f.type='file';f.accept='.json,application/json';f.onchange=async()=>{try{if(f.files[0].size>5e6)throw Error('Backup too large.');const next=validateBackup(JSON.parse(await f.files[0].text()));storePendingImport(next);}catch(err){toast('Could not import: '+err.message);}};f.click();break;}case'confirm-import':state={...blank(),...pendingImport,settings:{...blank().settings,...pendingImport.settings}};pendingImport=null;closeDialog();save();go('/profile');render();toast('Backup restored.');break;case'show-install-sheet':case'install':showInstallSheet();break;}});
let pendingImport=null;function storePendingImport(s){pendingImport=s;dialog('Replace local study data?','Importing this backup replaces your current profile, progress and quiz history.',btn('Cancel','cancel','button outline')+btn('Restore backup','confirm-import','button primary'));}
document.addEventListener('change',e=>{let t=e.target;if(t.dataset.topic){state.topics[t.dataset.topic]=t.checked;if(state.settings.autoPlan)regenerate();save();render();}if(t.dataset.task){let task=state.tasks.find(v=>v.id===t.dataset.task);task.status=t.checked?'done':'pending';if(task.topic)state.topics[task.topic]=t.checked;if(state.settings.autoPlan)regenerate();save();render();}if(t.dataset.change==='pyq-unit'){unitFilter=t.value;render();}if(t.dataset.change==='pyq-year'){pyqYear=t.value;render();}if(t.id==='auto-plan'){state.settings.autoPlan=t.checked;save();}});
document.addEventListener('submit',e=>{let f=e.target;if(!f.id)return;e.preventDefault();let d=new FormData(f);switch(f.id){case'profile-form':state.profile={name:d.get('name').trim(),college:d.get('college').trim(),branch:d.get('branch')};if(!state.profile.name||!state.profile.college){toast('Please enter your name and college.');return;}save();go(route()[0]==='edit-profile'?'/profile':'/home');render();break;case'task-form':state.tasks.push({id:uid(),title:d.get('title').trim(),subject:d.get('subject'),date:d.get('date'),minutes:30,status:'pending',auto:false});save();render();toast('Study task added.');break;case'preferences-form':state.settings.goal=d.get('goal');state.settings.slot=d.get('slot');state.settings.availability=Array.from({length:7},(_,i)=>+d.get('day'+i));if(state.settings.autoPlan)regenerate();save();go('/profile');toast('Study preferences saved.');break;case'quiz-setup':startAttempt(f.dataset.subject,'master',null,d.get('unit'),+d.get('minutes'));break;}});
window.addEventListener('hashchange',()=>{let old=previousHash;captureOld(old);scrolls.set(old,window.scrollY);viewStates.set(old,{unitFilter,savedOnly,resultFilter,pyqKind,pyqYear});previousHash=location.hash;navigatorOpen=false;const view=viewStates.get(location.hash)||{};unitFilter=view.unitFilter||'all';savedOnly=view.savedOnly||false;resultFilter=view.resultFilter||'all';pyqKind=view.pyqKind||'original';pyqYear=view.pyqYear||'all';currentStart=null;render();let a=activeAttempt();if(a&&!a.finished&&!document.hidden)currentStart=Date.now();window.scrollTo(0,scrolls.get(location.hash)||0);});
function captureOld(hash){if(!hash.startsWith('#/attempt/'))return;let id=hash.split('/')[2],a=state.attempts.find(a=>a.id===id);if(a&&!a.finished&&currentStart!==null){let now=Date.now();a.times=recordTime(a.times,a.index,currentStart,now);a.elapsed+=Math.max(0,(now-currentStart)/1000);save();}currentStart=null;}
document.addEventListener('visibilitychange',()=>{if(document.hidden){capture();currentStart=null;}else if(activeAttempt()&&!activeAttempt().finished&&!$('#modal').open)currentStart=Date.now();});
window.addEventListener('pagehide',()=>capture());
setInterval(()=>{let a=activeAttempt();if(a&&!a.finished&&currentStart!==null){capture();let timer=$('#timer');if(timer)timer.textContent=time(a.limit?Math.max(0,a.limit-a.elapsed):a.elapsed);if(a.limit&&a.elapsed>=a.limit){if($('#modal').open)closeDialog();finish(a);toast('Time is up. Your quiz has been submitted.');}}},1000);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('appinstalled',()=>{localStorage.setItem('pwa_installed','true');toast('✓ BEU Exam Dost PWA installed successfully!');render();});
window.addEventListener('resize',()=>checkDesktopNotice());
window.addEventListener('online',()=>toast('You’re back online.'));window.addEventListener('offline',()=>toast('Offline mode · Your saved content is available.'));
installUpdates({canReload:()=>!(activeAttempt()&&!activeAttempt().finished)&&!$('#modal').open,beforeReload:()=>{capture();save();return storageOK;},onReady:()=>toast('Offline ready · App content saved on this device.'),onDeferred:()=>toast('Update downloaded. It will apply after your current work.')} );
render();if(activeAttempt()&&!activeAttempt().finished)currentStart=Date.now();if(!storageOK)toast('Saved data could not be read. Import a backup if needed.');

$('#modal').addEventListener('cancel',()=>{let a=activeAttempt();if(a&&!a.finished&&!document.hidden)currentStart=Date.now();});
